<script setup lang="ts">

import{nextTick,onBeforeUnmount,onMounted,ref,watch}from'vue'
const props=defineProps<{collapsed?:boolean;mobileOpen?:boolean;label?:string}>();const emit=defineEmits<{'update:collapsed':[value:boolean];'update:mobileOpen':[value:boolean]}>()
const mobile=ref(typeof window!=='undefined'&&window.innerWidth<900),drawer=ref<HTMLDialogElement|null>(null)
let returnFocus:HTMLElement|null=null,previousOverflow=''
async function sync(){await nextTick();const dialog=drawer.value;if(!dialog)return;if(props.mobileOpen&&mobile.value){if(!dialog.open){returnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';dialog.showModal?.()}}else if(dialog.open)dialog.close()}
function closed(){document.body.style.overflow=previousOverflow;emit('update:mobileOpen',false);returnFocus?.focus()}
function resize(){mobile.value=window.innerWidth<900;if(!mobile.value&&props.mobileOpen){emit('update:mobileOpen',false);document.body.style.overflow=previousOverflow}void sync()}
watch(()=>props.mobileOpen,sync);watch(mobile,sync)
onMounted(()=>{window.addEventListener('resize',resize);void sync()});onBeforeUnmount(()=>{window.removeEventListener('resize',resize);if(drawer.value?.open)drawer.value.close();document.body.style.overflow=previousOverflow})

</script>
<template><component :is="mobile?'dialog':'aside'" v-if="mobile||!collapsed" ref="drawer" class="ui-app-sidebar" :class="{'ui-app-sidebar--drawer':mobile}" :aria-label="label||'Navigation'" @cancel="emit('update:mobileOpen',false)" @close="closed" @click="mobile&&$event.target===$event.currentTarget&&emit('update:mobileOpen',false)"><div class="ui-sidebar-frame"><div class="ui-sidebar-workspace"><slot name="workspace"/><button v-if="mobile" class="ui-icon-button" type="button" aria-label="关闭导航" @click="emit('update:mobileOpen',false)">×</button><button v-else class="ui-icon-button" type="button" aria-label="收起侧栏" @click="emit('update:collapsed',true)">‹</button></div><div class="ui-sidebar-navigation"><slot name="primary"/><slot name="secondary"/><slot/></div><footer class="ui-sidebar-footer"><slot name="footer"/></footer><div data-overlay-host/></div></component></template>
<style scoped>.ui-app-sidebar{position:sticky;top:0;z-index:25;width:240px;min-width:240px;height:100vh;height:100dvh;padding:0;border:0;background:var(--surface-sidebar);color:var(--text-primary)}.ui-sidebar-frame{height:100%;display:flex;flex-direction:column;padding:max(12px,env(safe-area-inset-top)) 8px max(12px,env(safe-area-inset-bottom));min-height:0}.ui-sidebar-workspace{display:flex;align-items:center;justify-content:space-between;min-height:44px;padding:0 4px;gap:8px}.ui-sidebar-navigation{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:8px 0}.ui-sidebar-footer{padding:8px 0 0}.ui-app-sidebar--drawer{position:fixed;inset:0 auto 0 0;width:min(288px,calc(100vw - 48px));min-width:0;max-width:none;max-height:none;margin:0;overflow:visible}.ui-app-sidebar--drawer::backdrop{background:var(--overlay-dim)}@media(min-width:900px) and (max-width:1199px){.ui-app-sidebar{width:224px;min-width:224px}}</style>
